            return []
        return convertTreeToDfsList(node.left) + [node] + convertTreeToDfsList(node.right)

    # 중위 순회
    def inorderTraversal(node):
        if not node:
            return []
        return inorderTraversal(node.left) + [node] + inorderTraversal(node.right)

    # 이진 트리 변환
    dfsList = convertTreeToDfsList(root)

    # 중위 순회
    inorderList = inorderTraversal(dfsList)

